const listWorkOrders = `-- name: ListWorkOrders :many

SELECT w.id, w.doc_no, w.doc_date, w.status, w.plan_qty, w.due_date, w.processing_cost, w.note, w.updated_at,
       i.code AS item_code, i.name AS item_name, u.name AS unit_name, wh.name AS warehouse_name,
       cu.name AS created_by_name
FROM work_orders w
JOIN items i ON i.id = w.item_id JOIN units u ON u.id = i.base_unit_id
JOIN warehouses wh ON wh.id = w.warehouse_id
LEFT JOIN users cu ON cu.id = w.created_by
WHERE w.company_id = $1
  AND ($2::text IS NULL OR w.status = $2)
  AND ($3::bigint IS NULL OR w.item_id = $3)
  AND ($4::date IS NULL OR w.doc_date >= $4)
  AND ($5::date IS NULL OR w.doc_date <= $5)
  AND ($6::text IS NULL OR w.doc_no ILIKE '%' || $6 || '%'
       OR i.code ILIKE '%' || $6 || '%' OR i.name ILIKE '%' || $6 || '%')
ORDER BY w.doc_date DESC, w.id DESC
LIMIT $8 OFFSET $7
`

type ListWorkOrdersParams struct {
	CompanyID int64
	Status    *string
	ItemID    *int64
	FromDate  *time.Time
	ToDate    *time.Time
	Keyword   *string
	Off       int32
	Lim       int32
}

type ListWorkOrdersRow struct {
	ID             int64
	DocNo          string
	DocDate        time.Time
	Status         string
	PlanQty        decimal.Decimal
	DueDate        *time.Time
	ProcessingCost decimal.Decimal
	Note           string
	UpdatedAt      time.Time
	ItemCode       string
	ItemName       string
	UnitName       string
	WarehouseName  string
	CreatedByName  *string
}

// ======== 工單 ========
func (q *Queries) ListWorkOrders(ctx context.Context, arg ListWorkOrdersParams) ([]ListWorkOrdersRow, error) {
	rows, err := q.db.Query(ctx, listWorkOrders,
		arg.CompanyID,
		arg.Status,
		arg.ItemID,
		arg.FromDate,
		arg.ToDate,
		arg.Keyword,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWorkOrdersRow{}
	for rows.Next() {
		var i ListWorkOrdersRow
		if err := rows.Scan(
			&i.ID,
			&i.DocNo,
			&i.DocDate,
			&i.Status,
			&i.PlanQty,
			&i.DueDate,
			&i.ProcessingCost,
			&i.Note,
			&i.UpdatedAt,
			&i.ItemCode,
			&i.ItemName,
			&i.UnitName,
			&i.WarehouseName,
			&i.CreatedByName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

