const productionConsumption = `-- name: ProductionConsumption :many

SELECT w.item_id AS output_item_id, t.item_id AS material_id, SUM(t.qty)::numeric AS qty
FROM inventory_transactions t JOIN work_orders w ON w.id = t.source_id
WHERE t.company_id = $1 AND t.source_type = 'work_order_issue'
  AND t.doc_date BETWEEN $2::date AND $3::date
GROUP BY w.item_id, t.item_id
HAVING SUM(t.qty) <> 0
`

type ProductionConsumptionParams struct {
	CompanyID int64
	StartDate time.Time
	EndDate   time.Time
}

type ProductionConsumptionRow struct {
	OutputItemID int64
	MaterialID   int64
	Qty          decimal.Decimal
}

// ======== 月結成本:生產 ========
// 期間內已過帳工單領用的材料:(成品, 材料) 的領用數量(負),含沖銷分錄所以反過帳的工單會互抵為 0
func (q *Queries) ProductionConsumption(ctx context.Context, arg ProductionConsumptionParams) ([]ProductionConsumptionRow, error) {
	rows, err := q.db.Query(ctx, productionConsumption, arg.CompanyID, arg.StartDate, arg.EndDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProductionConsumptionRow{}
	for rows.Next() {
		var i ProductionConsumptionRow
		if err := rows.Scan(&i.OutputItemID, &i.MaterialID, &i.Qty); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

