const writebackProduceCost = `-- name: WritebackProduceCost :exec
UPDATE inventory_transactions SET unit_cost = $1
WHERE company_id = $2 AND item_id = $3 AND source_type = 'work_order_receipt'
  AND doc_date BETWEEN $4::date AND $5::date
`

type WritebackProduceCostParams struct {
	UnitCost  *decimal.Decimal
	CompanyID int64
	ItemID    int64
	StartDate time.Time
	EndDate   time.Time
}

// 完工入庫的單位成本 = 該成品當月的完工成本 ÷ 完工數量
func (q *Queries) WritebackProduceCost(ctx context.Context, arg WritebackProduceCostParams) error {
	_, err := q.db.Exec(ctx, writebackProduceCost,
		arg.UnitCost,
		arg.CompanyID,
		arg.ItemID,
		arg.StartDate,
		arg.EndDate,
	)
	return err
}
